/*
Grammar (prefix style):
formula :=
    'T'
  | 'F'
  | 'a'..'k'
  | 'N' formula
  | 'K' formula formula   // AND
  | 'A' formula formula   // OR
  | 'C' formula formula   // implication

Input may contain '=' between two formulas; the equation is an identity
iff left and right are equal for all assignments.
*/

int eval_formula(int mask) {
    char c = s[pos++];

    if (c == 'T') return 1;
    if (c == 'F') return 0;
    if (c >= 'a' && c <= 'k') return (mask >> (c - 'a')) & 1;
    if (c == 'N') return !eval_formula(mask);
    if (c == 'K') {
        int x = eval_formula(mask);
        int y = eval_formula(mask);
        return x && y;
    }
    if (c == 'A') {
        int x = eval_formula(mask);
        int y = eval_formula(mask);
        return x || y;
    }
    if (c == 'C') {
        int x = eval_formula(mask);
        int y = eval_formula(mask);
        return (!x) || y;
    }

    return 0;
}

void collect_vars(const char *str) {
    varmask = 0;
    for (int i = 0; str[i]; i++) {
        if (str[i] >= 'a' && str[i] <= 'k') {
            varmask |= 1 << (str[i] - 'a');
        }
    }
}

