        while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
            s[--len] = '\0';
        }

        if (len == 0) continue;

        collect_vars(s);

        int eq = -1;
        for (int i = 0; s[i]; i++) {
            if (s[i] == '=') {
                eq = i;
                break;
            }
        }

        int identity = 1;
        int total = 1 << 11; /* variables a..k */

        for (int mask = 0; mask < total && identity; mask++) {
            pos = 0;
