        // must be variable or constant
        char c = s[pos];
        pos++;
        return getVal(c);
    };

    parse_imp = [&]() -> bool {
        bool left = parse_unary();
        while (pos < (int)s.size() && s[pos] == '>') {
            pos++; // skip '>'
            bool right = parse_unary();
            left = (!left) || right;
        }
        return left;
    };

    parse_and = [&]() -> bool {
        bool left = parse_imp();
        while (pos < (int)s.size() && s[pos] == '*') {
            pos++; // skip '*'
            bool right = parse_imp();
            left = left && right;
        }
        return left;
    };

    parse_or = [&]() -> bool {
        bool left = parse_and();
        while (pos < (int)s.size() && s[pos] == '+') {
            pos++; // skip '+'
            bool right = parse_and();
            left = left || right;
        }
        return left;
    };

    pos = 0;
    return parse_or();
