using namespace std;

struct Parser {
    string s;
    int pos = 0;
    int mask = 0; // values of variables a..k

    Parser(const string& str, int m) : s(str), mask(m) {}

    void skipSpaces() {
        while (pos < (int)s.size() && isspace((unsigned char)s[pos])) pos++;
    }

    bool match(const string& t) {
        skipSpaces();
        if (s.substr(pos, t.size()) == t) {
            pos += (int)t.size();
            return true;
        }
        return false;
    }

    bool parseEquation() {
        bool left = parseImp();
        skipSpaces();
        if (match("=")) {
            bool right = parseImp();
            return left == right;
        }
        return left;
    }

    // implication, right-associative
    bool parseImp() {
        bool left = parseOr();
        skipSpaces();
        if (match("->")) {
            bool right = parseImp();
            return (!left) || right;
        }
        return left;
    }

    // OR, left-associative
    bool parseOr() {
        bool val = parseAnd();
        while (true) {
            skipSpaces();
            if (match("|")) {
                bool rhs = parseAnd();
                val = val || rhs;
            } else {
                break;
            }
        }
        return val;
    }

    // AND, left-associative
    bool parseAnd() {
        bool val = parseNot();
        while (true) {
            skipSpaces();
            if (match("&")) {
                bool rhs = parseNot();
                val = val && rhs;
            } else {
                break;
            }
        }
        return val;
    }

    // NOT, highest precedence
    bool parseNot() {
        skipSpaces();
        if (match("!")) return !parseNot();
        return parsePrimary();
    }

    bool parsePrimary() {
        skipSpaces();
        if (match("(")) {
            bool val = parseImp();
            match(")");
            return val;
        }

        skipSpaces();
        if (pos >= (int)s.size()) return false;

        char c = s[pos++];
        if (c == 'T') return true;
        if (c == 'F') return false;
        if ('a' <= c && c <= 'k') {
            int bit = c - 'a';
            return (mask >> bit) & 1;
        }
        return false;
    }
};

