public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("")) continue;
            if (line.equals("#")) break;

            if (isIdentity(line)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
        sc.close();
    }

    static boolean isIdentity(String expr) {
        // variables a to k (11 variables)
        for (int mask = 0; mask < (1 << 11); mask++) {
            if (!evaluate(expr, mask)) {
                return false;
            }
        }
        return true;
    }

    static boolean evaluate(String expr, int mask) {
        // Convert to postfix using Shunting-yard
        StringBuilder postfix = new StringBuilder();
        Stack<Character> ops = new Stack<>();

        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == 'T') {
                postfix.append('1');
            } else if (c == 'F') {
                postfix.append('0');
            } else if (c >= 'a' && c <= 'k') {
                int bit = c - 'a';
                postfix.append((mask & (1 << bit)) != 0 ? '1' : '0');
            } else if (c == '-') {
                // negation, but next char is '>', skip
                ops.push('!');
                i++; // skip '>'
            } else if (c == '*') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    postfix.append(ops.pop());
                }
                ops.push('*');
            } else if (c == '+') {
                while (!ops.isEmpty() && ops.peek() != '(' && ops.peek() != '!') {
                    postfix.append(ops.pop());
                }
                ops.push('+');
            } else if (c == '>') {
                // implication
                while (!ops.isEmpty() && ops.peek() != '(') {
                    postfix.append(ops.pop());
                }
                ops.push('>');
            } else if (c == '(') {
                ops.push('(');
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    postfix.append(ops.pop());
                }
                ops.pop(); // remove '('
            }
        }
        while (!ops.isEmpty()) {
            postfix.append(ops.pop());
        }

        // Evaluate postfix
        Stack<Boolean> stack = new Stack<>();
        for (int i = 0; i < postfix.length(); i++) {
            char c = postfix.charAt(i);
            if (c == '1') {
                stack.push(true);
            } else if (c == '0') {
                stack.push(false);
            } else if (c == '!') {
                boolean a = stack.pop();
                stack.push(!a);
            } else if (c == '*') {
                boolean b = stack.pop();
                boolean a = stack.pop();
                stack.push(a && b);
            } else if (c == '+') {
                boolean b = stack.pop();
                boolean a = stack.pop();
                stack.push(a || b);
            } else if (c == '>') {
                boolean b = stack.pop();
                boolean a = stack.pop();
                stack.push(!a || b);
            }
        }
        return stack.pop();
    }
}

