public class Main {
    static class FastScanner {
        private final BufferedReader br;
        private String line;
        private int pos;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    static String s;
    static int idx;
    static boolean[] vars = new boolean[11];

    static boolean parseExpr() {
        skipSpaces();
        if (idx >= s.length()) return false;

        char c = s.charAt(idx);

        if (c == 'T') {
            idx++;
            return true;
        }
        if (c == 'F') {
            idx++;
            return false;
        }
        if (c >= 'a' && c <= 'k') {
            idx++;
            return vars[c - 'a'];
        }
        if (c == '(') {
            idx++; // '('
            boolean left = parseExpr();
            skipSpaces();

            if (idx < s.length() && s.charAt(idx) == ')') {
                idx++; // parenthesized expression
                return left;
            }

            String op = parseOp();
            boolean right = parseExpr();
            skipSpaces();
            if (idx < s.length() && s.charAt(idx) == ')') idx++;

            if (op.equals("&")) return left && right;
            if (op.equals("|")) return left || right;
            return (!left) || right; // ->
        }
        if (c == '-') { // unary negation
            idx++;
            return !parseExpr();
        }

        return false;
    }

    static String parseOp() {
        skipSpaces();
        if (s.startsWith("->", idx)) {
            idx += 2;
            return "->";
        }
        char c = s.charAt(idx);
        idx++;
        return String.valueOf(c);
    }

    static void skipSpaces() {
        while (idx < s.length() && Character.isWhitespace(s.charAt(idx))) idx++;
    }

    static boolean eval(String expr, int mask) {
        for (int i = 0; i < 11; i++) vars[i] = ((mask >> i) & 1) == 1;

        s = expr;
        idx = 0;
        boolean left = parseExpr();
        skipSpaces();

        // equation sign
        if (idx < s.length() && s.charAt(idx) == '=') idx++;
        skipSpaces();

        boolean right = parseExpr();
        return left == right;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String line = fs.nextLine();
            if (line == null) break;
            line = line.trim();
            if (line.isEmpty()) continue;
            if (line.equals("#")) break;

            boolean identity = true;
            for (int mask = 0; mask < (1 << 11); mask++) {
                if (!eval(line, mask)) {
                    identity = false;
                    break;
                }
            }
            out.append(identity ? "YES" : "NO").append('\n');
        }

        System.out.print(out.toString());
    }
