                elif tok == '(':
                    ops.append(tok)
                elif tok == ')':
                    while ops and ops[-1] != '(':
                        output.append(ops.pop())
                    ops.pop()  # remove '('
            while ops:
                output.append(ops.pop())

            # Evaluate postfix
            stack = []
            for tok in output:
                if isinstance(tok, int):
                    stack.append(tok)
                elif tok == 'NOT':
                    a = stack.pop()
                    stack.append(1 - a)
                elif tok == 'AND':
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(a & b)
                elif tok == 'OR':
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(a | b)
                elif tok == 'IMP':
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(1 if (a == 0 or b == 1) else 0)

            result = stack.pop()
            if result == 0:
                is_identity = False
                break

        print("YES" if is_identity else "NO")

if __name__ == "__main__":
    solve()

import sys
from itertools import product

def solve(equation):
    # Split on '=' but need to be careful about the equation
    # Find the '=' that separates LHS and RHS
    # The equation might be like "expr = expr"
    parts = equation.split('=')
    if len(parts) != 2:
        return "NO"
    lhs_str = parts[0].strip()
    rhs_str = parts[1].strip()

    # Find all variables (a-k)
    variables = sorted(set(c for c in equation if 'a' <= c <= 'k'))

    # Tokenize
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
            elif s[i:i+3] == 'NOT':
                tokens.append('NOT'); i += 3
            elif s[i:i+3] == 'AND':
                tokens.append('AND'); i += 3
            elif s[i:i+2] == 'OR':
                tokens.append('OR'); i += 2
            elif s[i:i+3] == 'IMP':
                tokens.append('IMP'); i += 3
            elif s[i] == 'T':
                tokens.append('T'); i += 1
            elif s[i] == 'F':
                tokens.append('F'); i += 1
            elif 'a' <= s[i] <= 'k':
                tokens.append(s[i]); i += 1
            elif s[i] in '()':
                tokens.append(s[i]); i += 1
            else:
                i += 1
        return tokens

    def parse(tokens, env):
        pos = [0]
        def peek(): return tokens[pos[0]] if pos[0] < len(tokens) else None
        def consume(): t = tokens[pos[0]]; pos[0] += 1; return t

        def parse_imp():
            left = parse_or()
            while peek() == 'IMP':
                consume()
                right = parse_or()
                left = (not left) or right
            return left

        def parse_or():
            left = parse_and()
            while peek() == 'OR':
                consume()
                right = parse_and()
                left = left or right
            return left

        def parse_and():
            left = parse_not()
            while peek() == 'AND':
                consume()
                right = parse_not()
                left = left and right
            return left

        def parse_not():
            if peek() == 'NOT':
                consume()
                return not parse_not()
            return parse_atom()

        def parse_atom():
            t = consume()
            if t == 'T': return True
            if t == 'F': return False
            if t == '(':
                val = parse_imp()
                consume()  # ')'
                return val
            return env[t]

        return parse_imp()

    lhs_tokens = tokenize(lhs_str)
    rhs_tokens = tokenize(rhs_str)

    n = len(variables)
    for vals in product([False, True], repeat=n):
        env = dict(zip(variables, vals))
        lhs_val = parse(lhs_tokens, env)
        rhs_val = parse(rhs_tokens, env)
        if lhs_val != rhs_val:
            return "NO"
    return "YES"

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    print(solve(line))

import sys

# Grammar (prefix notation):
# expression := 'T' | 'F' | variable('a'..'k') | 'N' expression | 'K' expression expression
#             | 'A' expression expression | 'C' expression expression
#
# Meanings:
# N: NOT
# K: AND
# A: OR
# C: implication (p -> q)

vars_list = [chr(ord('a') + i) for i in range(11)]  # a..k
var_index = {ch: i for i, ch in enumerate(vars_list)}

def eval_formula(s, pos, mask):
    ch = s[pos]
    if ch == 'T':
        return True, pos + 1
    if ch == 'F':
        return False, pos + 1
    if 'a' <= ch <= 'k':
        return ((mask >> var_index[ch]) & 1) == 1, pos + 1
    if ch == 'N':
        v, nxt = eval_formula(s, pos + 1, mask)
        return (not v), nxt
    if ch == 'K':
        v1, p1 = eval_formula(s, pos + 1, mask)
        v2, p2 = eval_formula(s, p1, mask)
        return (v1 and v2), p2
    if ch == 'A':
        v1, p1 = eval_formula(s, pos + 1, mask)
        v2, p2 = eval_formula(s, p1, mask)
        return (v1 or v2), p2
    if ch == 'C':
        v1, p1 = eval_formula(s, pos + 1, mask)
        v2, p2 = eval_formula(s, p1, mask)
        return ((not v1) or v2), p2
    return False, pos + 1  # should never happen for valid input

def is_tautology(expr):
    for mask in range(1 << 11):
        val, _ = eval_formula(expr, 0, mask)
        if not val:
            return False
    return True

def main():
    out = []
    for line in sys.stdin:
        expr = line.strip()
        if not expr:
            continue
        if expr == '0':
            break
        out.append('YES' if is_tautology(expr) else 'NO')
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()
